<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { isAuthFailure } from '../utils/session'
import { getApiErrorMessage, mailboxApi, tagApi } from '../api'
import type { EmailItem, Mailbox, Tag } from '../types'
import { formatDate } from '../utils/email'
const route = useRoute(); const router = useRouter(); const mailboxId = computed(() => Number(route.params.id))
const mailbox = ref<Mailbox | null>(null); const emails = ref<EmailItem[]>([]); const tags = ref<Tag[]>([]); const selectedTagIds = ref<number[]>([])
const loading = ref(false); const loadError = ref(false); const savingTags = ref(false); const deleting = ref(false); const copying = ref(false); const hasNew = ref(false)
let sequence = 0; let timer: ReturnType<typeof setTimeout> | undefined; let inFlight = false; let disposed = false
function sameEmails(a: EmailItem[], b: EmailItem[]) { return a.length === b.length && a.every((item, i) => item.id === b[i]?.id && item.received_at === b[i]?.received_at && item.is_read === b[i]?.is_read && item.verification_code === b[i]?.verification_code) }
async function load(initial = true) { const current = ++sequence; if (initial) { loading.value = true; loadError.value = false }; try { const [mailboxData, emailData, tagData] = await Promise.all([mailboxApi.get(mailboxId.value), mailboxApi.emails(mailboxId.value), tagApi.list()]); if (disposed || current !== sequence) return; const changed = !sameEmails(emails.value, emailData); mailbox.value = mailboxData; if (initial || !selectedTagIds.value.length) selectedTagIds.value = [...mailboxData.tag_ids]; if (changed && emails.value.length) hasNew.value = emailData.length > emails.value.length; emails.value = emailData; tags.value = tagData } catch (error) { if (initial) { loadError.value = true; if (!isAuthFailure(error)) ElMessage.error(getApiErrorMessage(error, '邮箱数据加载失败')) } } finally { if (initial && current === sequence) loading.value = false } }
function schedulePoll() { clearTimeout(timer); if (disposed || document.hidden) return; timer = setTimeout(async () => { if (!inFlight) { inFlight = true; try { await load(false) } finally { inFlight = false } } schedulePoll() }, 1000) }
function visibilityChanged() { if (document.hidden) clearTimeout(timer); else { void load(false); schedulePoll() } }
async function saveTags() { if (!mailbox.value || savingTags.value) return; const before = [...selectedTagIds.value]; savingTags.value = true; try { mailbox.value = await mailboxApi.update(mailbox.value.id, { tag_ids: selectedTagIds.value }); ElMessage.success('标签已保存') } catch (error) { selectedTagIds.value = before; if (!isAuthFailure(error)) ElMessage.error(getApiErrorMessage(error, '标签保存失败')) } finally { savingTags.value = false } }
async function removeMailbox() { if (!mailbox.value || deleting.value) return; deleting.value = true; try { await ElMessageBox.confirm(`删除后将同时移除“${mailbox.value.email_address}”的邮件和附件，且无法恢复。确定继续吗？`, '删除邮箱', { confirmButtonText: '确认删除', cancelButtonText: '取消', type: 'warning' }); await mailboxApi.remove(mailbox.value.id); ElMessage.success('邮箱已删除'); router.replace('/mailboxes') } catch (error) { if (error !== 'cancel' && !isAuthFailure(error)) ElMessage.error(getApiErrorMessage(error, '邮箱删除失败')) } finally { deleting.value = false } }
async function copyAddress() { if (!mailbox.value || copying.value) return; copying.value = true; try { await navigator.clipboard.writeText(mailbox.value.email_address); ElMessage.success('邮箱地址已复制') } catch { ElMessage.error('复制失败，请检查浏览器权限') } finally { copying.value = false } }
function openEmail(row: EmailItem) { router.push(`/emails/${row.id}`) }
watch(() => route.params.id, () => { void load(); schedulePoll() }); onMounted(() => { disposed = false; void load(); document.addEventListener('visibilitychange', visibilityChanged); schedulePoll() }); onBeforeUnmount(() => { disposed = true; sequence++; clearTimeout(timer); document.removeEventListener('visibilitychange', visibilityChanged) })
</script>
<template>
  <div v-loading="loading"><el-result v-if="loadError" icon="error" title="邮箱详情暂时无法加载" sub-title="请检查网络后重试"><template #extra><el-button type="primary" :loading="loading" @click="load()">重新加载</el-button><el-button @click="router.push('/mailboxes')">返回邮箱</el-button></template></el-result><template v-else><div class="page-heading"><div><el-button link class="back-button" @click="router.push('/mailboxes')">返回邮箱</el-button><div class="mailbox-title-row"><h1>{{ mailbox?.email_address || '邮箱详情' }}</h1><el-button link type="primary" :loading="copying" @click.stop="copyAddress">复制地址</el-button></div><p>{{ mailbox?.display_name || '接收邮箱' }} · 共 {{ emails.length }} 封邮件</p></div><div class="page-actions"><el-button v-if="mailbox" type="primary" @click="router.push({ path: '/outbound/new', query: { sender: mailbox.id } })">发送邮件</el-button><el-button :loading="loading" @click="load()">刷新</el-button></div></div><el-alert v-if="hasNew" title="有新邮件到达" type="success" show-icon closable @close="hasNew = false" /><el-card class="panel-card tag-assignment-card" shadow="never"><template #header><div class="card-header-row"><strong>邮箱标签</strong><span class="muted">单击已选标签取消、单击未选标签添加</span></div></template><div class="tag-zones"><section><h3>可选标签</h3><div class="tag-pills"><button v-for="tag in tags.filter(tag => !selectedTagIds.includes(tag.id))" :key="tag.id" type="button" class="tag-pill" @click="selectedTagIds.push(tag.id)">{{ tag.name }}</button><span v-if="!tags.some(tag => !selectedTagIds.includes(tag.id))" class="muted">暂无可选标签</span></div></section><section><h3>已选标签</h3><div class="tag-pills"><button v-for="id in selectedTagIds" :key="id" type="button" class="tag-pill is-selected" @click="selectedTagIds = selectedTagIds.filter(value => value !== id)">{{ tags.find(tag => tag.id === id)?.name || `#${id}` }}</button><span v-if="!selectedTagIds.length" class="muted">尚未选择标签</span></div></section></div><div class="tag-assignment-actions"><el-button type="primary" :loading="savingTags" @click="saveTags">保存标签</el-button><el-button @click="router.push('/tags')">管理标签</el-button></div></el-card><el-card class="panel-card mail-list-card" shadow="never"><template #header><div class="card-header-row"><strong>邮件列表</strong><span class="muted">每秒检查新邮件</span></div></template><el-table :data="emails" stripe empty-text="暂无邮件" @row-click="openEmail"><el-table-column label="状态" width="85"><template #default="{ row }"><el-tag :type="row.is_read ? 'info' : 'warning'">{{ row.is_read ? '已读' : '未读' }}</el-tag></template></el-table-column><el-table-column prop="sender" label="发件人" min-width="220" show-overflow-tooltip /><el-table-column prop="subject" label="主题" min-width="260" show-overflow-tooltip /><el-table-column label="验证码" width="130"><template #default="{ row }"><span v-if="row.verification_code" class="code-chip">{{ row.verification_code }}</span><span v-else class="muted">暂无</span></template></el-table-column><el-table-column label="接收时间" min-width="190"><template #default="{ row }">{{ formatDate(row.received_at) }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click.stop="openEmail(row)">打开</el-button></template></el-table-column></el-table></el-card><el-card class="panel-card danger-zone" shadow="never"><div class="card-header-row"><div><strong>危险操作</strong><p class="muted">删除邮箱会永久移除其中的邮件和附件。</p></div><el-button type="danger" plain :loading="deleting" @click="removeMailbox">删除邮箱</el-button></div></el-card></template></div>
</template>
